# Mock data
products = [
    {"id": 1, "name": "Laptop", "category": "Electronics"},
    {"id": 2, "name": "Blender", "category": "Appliances"},
    {"id": 3, "name": "Smartphone", "category": "Electronics"},
    {"id": 4, "name": "Toaster", "category": "Appliances"},
    {"id": 5, "name": "Headphones", "category": "Electronics"}
