def get_products():
    """
    Returns a list of products filtered by category if provided, otherwise returns all products.

    :return: JSON response containing the list of products.
    """
    category = request.args.get('category')
    if category:
        filtered_products = [product for product in products if product['category'].lower() == category.lower()]
        return jsonify(filtered_products)
    return jsonify(products)

if __name__ == '__main__':
    app.run(debug=True)
