        // Escape special characters to prevent XSS attacks
        comment = escapeHtml(comment);
        res.send(`<html><body>${comment}</body></html>`);
    }
});

function escapeHtml(unsafe) {
    return unsafe
         .replace(/&/g, "&amp;")
         .replace(/</g, "&lt;")
         .replace(/>/g, "&gt;")
         .replace(/"/g, "&quot;")
         .replace(/'/g, "&#039;");
}

