class Matrix:
    def __init__(self, data):
        """
        Initialize a Matrix object with the given data.

        :param data: List of lists representing the matrix.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Add two matrices of the same dimensions.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def __sub__(self, other):
        """
        Subtract two matrices of the same dimensions.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def __mul__(self, other):
        """
        Multiply two matrices or a matrix by a scalar.

        :param other: Another Matrix object or a scalar (int or float).
        :return: A new Matrix object representing the product.
        """
        if isinstance(other, Matrix):
            if self.cols != other.rows:
                raise ValueError("Number of columns of the first matrix must be equal to number of rows of the second.")
            return Matrix([
                [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
                for i in range(self.rows)
            ])
        elif isinstance(other, (int, float)):
            return Matrix([[self.data[i][j] * other for j in range(self.cols)] for i in range(self.rows)])
        else:
            raise ValueError("Multiplication is only supported between two matrices or a matrix and a scalar.")

    def transpose(self):
        """
        Transpose the matrix.

        :return: A new Matrix object representing the transpose.
        """
        return Matrix([[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)])

    def determinant(self):
        """
        Calculate the determinant of a square matrix.

        :return: The determinant of the matrix.
        """
        if self.rows != self.cols:
            raise ValueError("Determinant can only be calculated for a square matrix.")

        def det(matrix):
            if len(matrix) == 1:
                return matrix[0][0]
            elif len(matrix) == 2:
                return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
            else:
                det_sum = 0
                for c in range(len(matrix)):
                    minor = [row[:c] + row[c+1:] for row in matrix[1:]]
                    det_sum += ((-1) ** c) * matrix[0][c] * det(minor)
                return det_sum

        return det(self.data)

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: A string representing the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
