```python
from typing import List, Dict, Union

def generate_report(teams: List[Dict[str, Union[int, str, List[Dict[str, Union[str, int]]]]]) -> List[Dict[str, Union[int, str, float]]]:
    report = []
    for team in teams:
        total_score = team["score"] + sum(task["taskScore"] for task in team["taskStats"])
        average_task_score = sum(task["taskScore"] for task in team["taskStats"]) / len(team["taskStats"])
        report.append({"id": team["id"], "totalScore": total_score, "averageTaskScore": average_task_score})
    return report

