                        callback.Continue(acceptFilters.FindIndex(filter => filter == Path.GetExtension(dialog.FileName)), dialog.FileNames.ToList());
                    }
                    else{
                        callback.Cancel();
                    }

                    callback.Dispose();
                }

                return true;
            }
            else{
                callback.Dispose();
                return false;
            }
        }
    }
