import csv

def print_first_five_rows(file_path):
    """
    Reads a CSV file and prints the first five rows after the header.
    Handles exceptions such as file not found, permission errors, and CSV errors.

    :param file_path: Path to the CSV file.
    """
    try:
        with open(file_path, mode='r', newline='') as file:
            csv_reader = csv.reader(file)
            next(csv_reader)  # Skip the header row
            for _ in range(5):
                try:
                    row = next(csv_reader)
                    print(row)
                except StopIteration:
                    break
    except FileNotFoundError:
        print(f"Error: The file '{file_path}' was not found.")
    except PermissionError:
        print(f"Error: Permission denied when trying to read the file '{file_path}'.")
    except csv.Error as e:
        print(f"Error reading CSV file '{file_path}': {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

# Usage
print_first_five_rows('data.csv')
