import subprocess
import os

def is_process_running(process_name):
    try:
        subprocess.check_output(["pidof", process_name])
        return True
    except subprocess.CalledProcessError:
        return False

def start_process(process_path):
    try:
        subprocess.Popen([process_path])
        print(f"Started {process_path}")
    except Exception as e:
        print(f"Error starting {process_path}: {e}")

def stop_and_start_process(process_name, process_path):
    try:
        subprocess.run(["pkill", process_name])
        print(f"Stopped {process_name}")
        start_process(process_path)
    except Exception as e:
        print(f"Error stopping {process_name} or starting {process_path}: {e}")

