def is_balanced(s: str) -> bool:
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string containing various characters including parentheses.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    closing_to_opening = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in closing_to_opening:
            top_element = stack.pop() if stack else '#'
            if closing_to_opening[char] != top_element:
                return False
        elif char in closing_to_opening.values():
            stack.append(char)

    return not stack
