from twisted.internet.protocol import Protocol
from twisted.protocols.basic import LineReceiver
from twisted.cred import checkers, portal
from twisted.conch import avatar, recvline
from zope.interface import implementer
from twisted.internet import reactor


@implementer(avatar.IAvatar)
class ClientAvatar(object):
    def __init__(self, client, server):
        self.__client = client
        self.__server = server

    def send_message(self, message):
        if self.__server:
            self.__server.sendLine(message.encode('utf-8'))

    def receive_message(self, message):
        # Process the received message
        print("Received message:", message)


@implementer(avatar.IRealm)
class SimpleRealm(object):
    def requestAvatar(self, avatarId, mind, *interfaces):
        if avatar.IAvatar in interfaces:
            return interfaces[0], ClientAvatar(None, None), lambda: None
        raise NotImplementedError("This realm only supports the IAvatar interface")


class SimpleProtocol(LineReceiver):
    avatar = None

    def connectionMade(self):
        self.sendLine("Connected to the server.".encode('utf-8'))

    def lineReceived(self, line):
        if self.avatar:
            self.avatar.receive_message(line.decode('utf-8'))

    def connectionLost(self, reason):
        if self.avatar:
            self.avatar.__client = None
            self.avatar.__server = None


class SimpleProtocolFactory(protocol.Factory):
    def buildProtocol(self, addr):
        return SimpleProtocol()


def main():
    p = portal.Portal(SimpleRealm())
    p.registerChecker(checkers.AllowAnonymousAccess())
    f = SimpleProtocolFactory()
    f.protocol.avatar = ClientAvatar(None, None)
    reactor.listenTCP(1234, f)
    reactor.run()


if __name__ == '__main__':
    main()
