class Calculator:
    def add(self, a, b):
        """Return the sum of a and b."""
        return a + b

    def subtract(self, a, b):
        """Return the difference of a and b."""
        return a - b

    def multiply(self, a, b):
        """Return the product of a and b."""
        return a * b

    def divide(self, a, b):
        """Return the quotient of a and b, or an error message if b is zero."""
        if b == 0:
            return "Error: Division by zero"
        return a / b

    def calculate(self, expression):
        """
        Evaluate the arithmetic expression provided as a string.
        Return the result or an error message if the expression is invalid.
        """
        try:
            operators = {
                '+': self.add,
                '-': self.subtract,
                '*': self.multiply,
                '/': self.divide
            }
            tokens = expression.split()
            a = float(tokens[0])
            for i in range(1, len(tokens), 2):
                operator = tokens[i]
                b = float(tokens[i + 1])
                if operator not in operators:
                    return "Error: Unsupported operator"
                a = operators[operator](a, b)
                if isinstance(a, str) and "Error" in a:
                    return a
            return a
        except (IndexError, ValueError):
            return "Error: Invalid expression"
