Here is a simple C++ program that checks whether a binary tree is a binary search tree:

```C++
#include<iostream>
using namespace std;

struct Node
{
    int data;
    Node* left;
    Node* right;
};

// Function to create a new Node in heap
Node* NewNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

// To insert data in BST, returns address of root node 
Node* Insert(Node* root,int data)
{
    if(root == NULL)        // empty tree
    {
        root = NewNode(data);
    }
    else if(data <= root->data)
    {
        root->left = Insert(root->left,data);
    }
    else
    {
        root->right = Insert(root->right,data);
    }
    return root;
}

//Function to check if Binary Tree is a Binary Search Tree
bool isBST(Node* root, Node* left=NULL, Node* right=NULL)
{
    if(root == NULL)
        return true;

    if (left != NULL && root->data <= left->data)
        return false;

    if (right != NULL && root->data >= right->data)
        return false;

    return isBST(root->left, left, root) and
           isBST(root->right, root, right);
}

int main()
{
   Node* root = NULL;
   root = Insert(root,5); root = Insert(root,10);
   root = Insert(root,3); root = Insert(root,4); 
   root = Insert(root,1); root = Insert(root,11);

   if(isBST(root,nullptr,nullptr))
       cout<<"Is BST.";
   else
       cout<<"Is not BST.";

   return 0;
}
```
This program first creates a binary search tree and then checks if the created tree is a BST or not. This is done using a helper function `isBST()`, which checks for every node in tree, whether the current node's value is in range `(left, right)`. At first, the range is `(NULL, NULL)`, so any node value will be acceptable.

