def find_longest_increasing_subsequence(sequence):
    """
    Determine the length of the longest increasing subsequence in a given list of integers.

    :param sequence: List of integers representing the sequence.
    :return: Integer representing the length of the longest increasing subsequence.
    """
    if not sequence:
        return 0

    dp = [1] * len(sequence)

    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# Example usage:
