import json

def flatten_json(json_string):
    """
    Flattens a nested JSON string into a single-level dictionary.

    Parameters:
    json_string (str): A JSON string representing a nested object.

    Returns:
    dict: A dictionary with flattened keys and corresponding values.
    """
    try:
        out = {}

        def flatten(x, name=''):
            if isinstance(x, dict):
                for a in x:
                    flatten(x[a], name + a + '.')
            elif isinstance(x, list):
                for i, a in enumerate(x):
                    flatten(a, name + str(i) + '.')
            else:
                out[name[:-1]] = x

        flatten(json.loads(json_string))
        return out
    except (json.JSONDecodeError, TypeError):
        return {}
