  const filteredCountries = countries.filter(
    (country) =>
      country.population >= populationRange[0] &&
      country.population <= populationRange[1] &&
      country.gdp >= gdpRange[0] &&
      country.gdp <= gdpRange[1] &&
      country.landArea >= landAreaRange[0] &&
      country.landArea <= landAreaRange[1]
  );

  // Step 4 & 8: Display filtered list of countries
  return (
    <div>
      <h1>Country List</h1>
      <div>
        <h2>Filter by Population Size</h2>
        <input
          type="range"
          min={0}
          max={100000000}
          value={populationRange[0]}
          onChange={(e) =>
            setPopulationRange([parseInt(e.target.value), populationRange[1]])
          }
        />
        <input
          type="range"
          min={0}
          max={100000000}
          value={populationRange[1]}
          onChange={(e) =>
            setPopulationRange([populationRange[0], parseInt(e.target.value)])
          }
        />
      </div>
      <div>
        <h2>Filter by GDP per Capita</h2>
        <input
          type="range"
          min={0}
          max={50000}
          value={gdpRange[0]}
          onChange={(e) =>
            setGdpRange([parseInt(e.target.value), gdpRange[1]])
          }
        />
        <input
          type="range"
          min={0}
          max={50000}
          value={gdpRange[1]}
          onChange={(e) =>
            setGdpRange([gdpRange[0], parseInt(e.target.value)])
          }
        />
      </div>
      <div>
        <h2>Filter by Land Area</h2>
        <input
          type="range"
          min={0}
          max={500000}
          value={landAreaRange[0]}
          onChange={(e) =>
            setLandAreaRange([parseInt(e.target.value), landAreaRange[1]])
          }
        />
        <input
          type="range"
          min={0}
          max={500000}
          value={landAreaRange[1]}
          onChange={(e) =>
            setLandAreaRange([landAreaRange[0], parseInt(e.target.value)])
          }
        />
      </div>
      <ul>
        {filteredCountries.map((country) => (
          <li key={country.name}>
            <h3>{country.name}</h3>
            <p>Population: {country.population}</p>
            <p>GDP per Capita: {country.gdp}</p>
            <p>Land Area: {country.landArea}</p>
