class BookInventory:
    def __init__(self):
        self.inventory = {}

    def add_book(self, title, author, quantity):
        """
        Adds `quantity` copies of the book with the given `title` and `author` to the inventory.
        """
        book_key = (title, author)
        if book_key in self.inventory:
            self.inventory[book_key] += quantity
        else:
            self.inventory[book_key] = quantity

    def remove_book(self, title, author, quantity):
        """
        Removes `quantity` copies of the book with the given `title` and `author` from the inventory.
        If the quantity to remove is greater than or equal to the current stock, the book is completely removed.
        """
        book_key = (title, author)
        if book_key in self.inventory:
            if self.inventory[book_key] <= quantity:
                del self.inventory[book_key]
            else:
                self.inventory[book_key] -= quantity

    def list_books(self):
        """
        Returns a list of dictionaries, each representing a book in the inventory with keys `title`, `author`, and `quantity`.
        """
        return [{'title': title, 'author': author, 'quantity': quantity} 
                for (title, author), quantity in self.inventory.items()]
