Here's how you might implement this function in Rust:

```rust
use std::collections::VecDeque;

fn advanced_encode(message: &str, shift: usize) -> String {
    let vowels = "aeiou";
    let consonants = "bcdfghjklmnpqrstvwxyz";
    let all_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    let trans = |string: &str, amount| {
        let mut chars: VecDeque<char> = string.chars().collect();
        chars.rotate_right(amount);
        let shift = chars.iter().collect::<String>();
        string.chars().zip(shift.chars()).collect::<Vec<(char, char)>>()
    };

    let mut trans_lowercase = trans(vowels, shift);
    trans_lowercase.append(&mut trans(consonants, shift));
    let trans_uppercase: Vec<(char, char)> = trans(vowels, shift)
        .into_iter()
        .map(|(a, b)| (a.to_uppercase().next().unwrap(), b.to_uppercase().next().unwrap()))
        .collect();
    let trans: Vec<(char, char)> = [trans_lowercase, trans_uppercase].concat();

    let mut encrypted_message = String::from(message);

    for (i, c) in message.chars().enumerate() {
        if !c.is_ascii_alphabetic() {
            continue;
        }
        else {
            if let Some((_, trans_c)) = trans.iter().find(|&(x, _)| *x == c) {
                let pos = all_chars.find(*trans_c).unwrap();
                encrypted_message.push(all_chars.chars().nth((pos + i * shift * ((*trans_c as u32) as usize)) % all_chars.len()).unwrap());
            }
            else {
                encrypted_message.push(c)
            }
        }
    }

    encrypted_message
}
```

This code creates the same vowel and consonant shifts like in the Python code. With the `trans` closure it generates a translation mapping from the original character to the shifted one. The `message` is iterated character by character. If a character is not an ascii letter, it's left as it is, otherwise it's translated based on the `trans` mapping. Then each translated letter's position is calculated in the `all_chars` string, to which the displacement (`i * shift * aschii representation`) is added. All this modulo the length of `all_chars` is the index of the newly encrypted character in `all_chars`.

Note: this Rust function uses character rotation and dynamic type (VecDeque), and transformation functions found in `String` and `Option`. The similar result could be achieved with other logic and Rust's types.

