```python
class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def is_square(self):
        """
        Returns True if the matrix is square, otherwise False.
        """
        return self.rows == self.cols

    def __add__(self, other):
        """
        Adds two matrices and returns the resulting matrix.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to add")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts the second matrix from the first and returns the resulting matrix.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to subtract")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices and returns the resulting matrix.
        """
        if self.cols != other.rows:
            raise ValueError("The number of columns in the first matrix must be equal to the number of rows in the second matrix")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def determinant(self):
        """
        Computes the determinant of the matrix.
        """
        if not self.is_square():
            raise ValueError("Determinant is defined only for square matrices")

        if self.rows == 1:
            return self.data[0][0]
        elif self.rows == 2:
            return self.data[0][0] * self.data[1][1] - self.data[0][1] * self.data[1][0]
        else:
            det = 0
            for i in range(self.cols):
                submatrix = [
                    row[:i] + row[i+1:] for row in self.data[1:]
                ]
                det += ((-1) ** i) * self.data[0][i] * Matrix(submatrix).determinant()
            return det

    def inverse(self):
        """
        Returns the inverse of the matrix if it exists, otherwise raises a ValueError.
        """
        det = self.determinant()
        if det == 0:
            raise ValueError("Matrix is singular, cannot be inverted")

        cofactors = []
        for i in range(self.rows):
            cofactor_row = []
            for j in range(self.cols):
                minor = [
                    row[:j] + row[j+1:] for row in (self.data[:i] + self.data[i+1:])
                ]
                cofactor_row.append(((-1) ** (i + j)) * Matrix(minor).determinant())
            cofactors.append(cofactor_row)

        adjugate = list(map(list, zip(*cofactors)))  # Transpose
        inv_det = 1 / det

        result = [
            [inv_det * adjugate[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]

        # Ensure the elements are integers if possible
        result = [
            [int(e) if isinstance(e, float) and e.is_integer() else e for e in row]
            for row in result
        ]

        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
