def topological_sort(graph):
    """
    Returns a topological ordering of the nodes in the given directed acyclic graph (DAG).
    If the graph contains a cycle, returns an empty list.

    :param graph: A dictionary representing the adjacency list of the graph.
    :return: A list of nodes in topological order, or an empty list if a cycle exists.
    """
    def dfs(node):
        if visited[node] == -1:
            return False
        if visited[node] == 1:
            return True
        visited[node] = -1
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        visited[node] = 1
        topo_order.append(node)
        return True

    visited = {node: 0 for node in graph}
    topo_order = []
    for node in graph:
        if not visited[node]:
            if not dfs(node):
                return []
    return topo_order[::-1]
