class OverloadedFunctions {
private:
    int data;

public:
    OverloadedFunctions() : data(0) {}

    void process(int& value) & {
        data += value;
    }

    void process(int&& value) && {
        data -= value;
    }

    int getData() const {
        return data;
    }
};

int main() {
