def validate_ip_address(ip):
    """
    Validates if the given string is a valid IPv4 address.

    :param ip: A string representing the IPv4 address to validate.
    :return: True if the IP address is valid, False otherwise.
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False
        if not 0 <= int(part) <= 255:
            return False
        if part != str(int(part)):
            return False
    return True
