import json

def extract_emails_from_json(json_file_path, output_file_path="emails.txt"):
    """
    Extracts unique email addresses from a JSON file and writes them to a text file.

    :param json_file_path: Path to the JSON file containing user data.
    :param output_file_path: Path to the output text file where emails will be written.
    """
    emails = set()  # Use a set to avoid duplicates
    try:
        with open(json_file_path, 'r', encoding='utf-8') as json_file:
            data = json.load(json_file)

            def extract_emails(obj):
                if isinstance(obj, dict):
                    for key, value in obj.items():
                        if key.lower() == 'email':
                            emails.add(value)
                        else:
                            extract_emails(value)
                elif isinstance(obj, list):
                    for item in obj:
                        extract_emails(item)

            extract_emails(data)

        with open(output_file_path, 'w', encoding='utf-8') as output_file:
            for email in emails:
                output_file.write(email + "\n")

        print(f"Successfully extracted {len(emails)} email addresses.")
    except FileNotFoundError:
        print(f"Error: The file {json_file_path} was not found.")
    except json.JSONDecodeError:
        print(f"Error: The file {json_file_path} is not a valid JSON file.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

