def validate_brackets(s: str) -> bool:
    """
    Determines if the brackets in the string are balanced.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the brackets are balanced, False otherwise.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_bracket:
            top_element = stack.pop() if stack else '#'
            if matching_bracket[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
