import csv

def calculate_customer_totals(input_file='transactions.csv', output_file='customer_totals.csv'):
    """
    Reads a CSV file containing customer transactions, calculates the total transaction amount for each customer,
    and writes the results to a new CSV file. Handles errors by printing messages and skipping problematic lines.

    :param input_file: Path to the input CSV file.
    :param output_file: Path to the output CSV file.
    """
    customer_totals = {}

    try:
        with open(input_file, mode='r', newline='') as infile:
            reader = csv.DictReader(infile)

            for line_number, row in enumerate(reader, start=1):
                try:
                    customer_id = row['customer_id']
                    transaction_id = row['transaction_id']
                    amount = float(row['amount'])  # Convert amount to float
                    timestamp = row['timestamp']

                    # Accumulate the amount for each customer
                    if customer_id in customer_totals:
                        customer_totals[customer_id] += amount
                    else:
                        customer_totals[customer_id] = amount

                except ValueError as e:
                    print(f"Error processing line {line_number}: {e}. Skipping this line.")
                    continue
                except KeyError as e:
                    print(f"Missing column in line {line_number}: {e}. Skipping this line.")
                    continue
                except Exception as e:
                    print(f"Unexpected error on line {line_number}: {e}. Skipping this line.")
                    continue

    except FileNotFoundError:
        print(f"File not found: {input_file}")
        return
    except Exception as e:
        print(f"An error occurred: {e}")
        return

    try:
        with open(output_file, mode='w', newline='') as outfile:
            writer = csv.writer(outfile)
            writer.writerow(['customer_id', 'total_amount'])

            for customer_id, total_amount in customer_totals.items():
                writer.writerow([customer_id, total_amount])

    except Exception as e:
        print(f"An error occurred while writing to the file {output_file}: {e}")

# Call the function to process the transactions
calculate_customer_totals()
